3	namespace App\Models\Core\Professional;
4	
5	use App\Models\Analytics\LinkClick;
6	use App\Models\Analytics\SiteVisit;
7	use App\Models\BaseModel;
8	use App\Models\Billing\Subscription;
9	use App\Models\Core\Notifications\EmailSubscription;
10	use App\Models\Core\Site\Block;
11	use App\Models\Core\Site\Site;
12	use Illuminate\Database\Eloquent\Builder;
13	use Illuminate\Database\Eloquent\Concerns\HasUuids;
14	use Illuminate\Database\Eloquent\Relations\HasMany;
15	use Illuminate\Database\Eloquent\Relations\HasOne;
16	use Illuminate\Database\Eloquent\Relations\Relation;
17	use Illuminate\Database\Eloquent\SoftDeletes;
18	
19	/**
20	 * @property string $id
21	 * @property string $auth_user_id
22	 * @property string $handle
23	 * @property string $display_name
24	 * @property int $onboarding_step
25	 */
26	
27	// V2: Central identity model. Both brands and affiliates are professionals distinguished by professional_type. Owns site, services, customers, integrations.
28	class Professional extends BaseModel
29	{
30	    use HasUuids, SoftDeletes;
31	
32	    protected $table = 'core.professionals';
33	
34	    public $incrementing = false;
35	
36	    protected $keyType = 'string';
37	
38	    protected $hidden = [
39	        'auth_user_id',
40	        'stripe_connect_account_id',
41	        'stripe_customer_id',
42	        'stripe_payment_method_id',
43	        'stripe_commission_funding_mode',
44	        'stripe_manual_balance_cents',
45	        'stripe_manual_balance_currency',
46	        'deletion_token_hash',
47	    ];
48	
49	    protected $fillable = [
50	        'handle',
51	        'display_name',
52	        'bio',
53	        'about',
54	        'country_code',
55	        'timezone',
56	        'professional_type',
57	        'status',
58	        'onboarding_step',
59	        'qr_slug',
60	        'phone',
61	        'primary_email',
62	        'first_name',
63	        'last_name',
64	
65	        // Public Accessible Contacts
66	        'public_contact_number',
67	        'public_contact_email',
68	
69	        // Location
70	        'location_street_address',
71	        'location_city',
72	        'location_state',
73	        'location_postcode',
74	        'location_country',
75	
76	        'handle_lc',
77	
78	        // Stripe Connect + commission funding
79	        'stripe_connect_account_id',
80	        'stripe_connect_status',
81	        'stripe_customer_id',
82	        'stripe_payment_method_id',
83	        'stripe_commission_funding_mode',
84	        'stripe_manual_balance_cents',
85	        'stripe_manual_balance_currency',
86	        'stripe_grace_period_ends_at',
87	
88	        // Account deletion lifecycle
89	        'deletion_token_hash',
90	        'deletion_requested_at',
91	        'deletion_confirmed_at',
92	        'deletion_previous_status',
93	    ];
94	
95	    protected $casts = [
96	        'onboarding_step' => 'integer',
97	        'stripe_manual_balance_cents' => 'integer',
98	        'stripe_grace_period_ends_at' => 'datetime',
99	        'about' => 'array',
100	        'created_at' => 'datetime',
101	        'updated_at' => 'datetime',
102	        'deleted_at' => 'datetime',
103	        'deletion_requested_at' => 'datetime',
104	        'deletion_confirmed_at' => 'datetime',
105	    ];
106	
107	    public function isInfluencer(): bool
108	    {
109	        return mb_strtolower(trim((string) ($this->professional_type ?? ''))) === 'influencer';
110	    }
111	
112	    public function isBrand(): bool
113	    {
114	        return mb_strtolower(trim((string) ($this->professional_type ?? ''))) === 'brand';
115	    }
116	
117	    public function isProfessional(): bool
118	    {
119	        return mb_strtolower(trim((string) ($this->professional_type ?? ''))) === 'professional';
120	    }
121	
122	    // Account is in the post-confirm grace period: read-only HTTP, write-blocked
123	    // policies. Canonical predicate — middleware and Policies both consult this
124	    // so the literal status string lives in exactly one place.
125	    public function isPendingDeletion(): bool
126	    {
127	        return mb_strtolower(trim((string) ($this->status ?? ''))) === 'pending_deletion';
128	    }
129	
130	    public function brandProfile(): HasOne
131	    {
132	        return $this->hasOne(BrandProfile::class, 'professional_id');
133	    }
134	
135	    public function site(): HasOne
136	    {
137	        return $this->hasOne(Site::class, 'professional_id');
138	    }
139	
140	    public function blocks(): HasMany
141	    {
142	        return $this->hasMany(Block::class, 'professional_id');
143	    }
144	
145	    public function linkBlocks(): HasMany
146	    {
147	        return $this->blocks()
148	            ->where('block_group', 'links')
149	            ->where('block_type', 'link')
150	            ->orderBy('sort_order');
151	    }
152	
153	    public function sectionBlocks(): HasMany
154	    {
155	        return $this->blocks()
156	            ->where('block_group', 'sections')
157	            ->orderBy('sort_order');
158	    }
159	
160	    public function customers(): HasMany
161	    {
162	        return $this->hasMany(Customer::class, 'professional_id')
163	            ->orderByDesc('created_at');
164	    }
165	
166	    public function siteVisits(): HasMany
167	    {
168	        return $this->hasMany(SiteVisit::class, 'professional_id');
169	    }
170	
171	    public function linkClicks(): HasMany
172	    {
173	        return $this->hasMany(LinkClick::class, 'professional_id');
174	    }
175	
176	    public function services(): HasMany
177	    {
178	        return $this->hasMany(Service::class, 'professional_id');
179	    }
180	
181	    public function serviceCategories()
182	    {
183	        return $this->hasMany(ServiceCategory::class);
184	    }
185	
186	    public function emailSubscriptions(): HasMany
187	    {
188	        return $this->hasMany(EmailSubscription::class, 'professional_id');
189	    }
190	
191	    public function brandAffiliateInvites(): HasMany
192	    {
193	        return $this->hasMany(BrandAffiliateInvite::class, 'brand_professional_id')
194	            ->orderByDesc('created_at');
195	    }
196	
197	    /**
198	     * All brand connections where this professional is the affiliate.
199	     * Empty for brand accounts (brands connect TO affiliates, not the reverse).
200	     */
201	    public function brandPartnerLinks(): HasMany
202	    {
203	        return $this->hasMany(BrandPartnerLink::class, 'affiliate_professional_id');
204	    }
205	
206	    /**
207	     * The affiliate's primary brand connection (slot 0). V2 uses a single-brand
208	     * model, so this is effectively "the brand" for an affiliate, or null for
209	     * an affiliate that hasn't connected yet / a brand account.
210	     */
211	    public function primaryBrandPartnerLink(): HasOne
212	    {
213	        return $this->hasOne(BrandPartnerLink::class, 'affiliate_professional_id')
214	            ->where('slot', 0);
215	    }
216	
217	    /**
218	     * Return the industries that drive this professional's experience.
219	     *
220	     * - Brand: its own BrandProfile.industries (primary at index 0).
221	     * - Affiliate (professional/influencer): the primary (slot=0) connected
222	     *   brand's industries. If multi-brand lands later, the "union across
223	     *   brands" decision is deferred — see docs/brand-industries.md §7.
224	     *
225	     * Always returns a clean array of string slugs; empty strings and
226	     * non-strings are filtered defensively (legacy free-form data could
227	     * contain either).
228	     *
229	     * @return array<int, string>
230	     */
231	    public function effectiveIndustries(): array
232	    {
233	        $industries = $this->isBrand()
234	            ? ($this->brandProfile?->industries ?? [])
235	            : ($this->primaryBrandPartnerLink?->brandProfessional?->brandProfile?->industries ?? []);
236	
237	        if (! is_array($industries)) {
238	            return [];
239	        }
240	
241	        return array_values(array_filter(
242	            $industries,
243	            static fn ($value) => is_string($value) && $value !== ''
244	        ));
245	    }
246	
247	    /**
248	     * First-is-primary convention: the first industry in the list is the
249	     * primary. Null when no industries are set.
250	     */
251	    public function primaryIndustry(): ?string
252	    {
253	        return $this->effectiveIndustries()[0] ?? null;
254	    }
255	
256	    public function subscription(): HasOne
257	    {
258	        return $this->hasOne(Subscription::class, 'professional_id');
259	    }
260	
261	    public function integrations(): HasMany
262	    {
263	        return $this->hasMany(ProfessionalIntegration::class, 'professional_id');
264	    }
265	
266	    public function squareIntegration(): HasOne
267	    {
268	        return $this->hasOne(ProfessionalIntegration::class, 'professional_id')
269	            ->where('provider', ProfessionalIntegration::PROVIDER_SQUARE);
270	    }
271	
272	    public function freshaIntegration(): HasOne
273	    {
274	        return $this->hasOne(ProfessionalIntegration::class, 'professional_id')
275	            ->where('provider', ProfessionalIntegration::PROVIDER_FRESHA);
276	    }
277	
278	    public function shopifyIntegration(): HasOne
279	    {
280	        return $this->hasOne(ProfessionalIntegration::class, 'professional_id')
281	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY);
282	    }
283	
284	    public function integrationForProvider(string $provider): ?ProfessionalIntegration
285	    {
286	        $provider = mb_strtolower(trim($provider));
287	
288	        if ($provider === '') {
289	            return null;
290	        }
291	
292	        if ($this->relationLoaded('integrations')) {
293	            return $this->integrations->firstWhere('provider', $provider);
294	        }
295	
296	        return $this->integrations()->where('provider', $provider)->first();
297	    }
298	
299	    public function resolveChildRouteBindingQuery($childType, $value, $field): Builder
300	    {
301	        $query = parent::resolveChildRouteBindingQuery($childType, $value, $field);
302	
303	        if ($query instanceof Relation) {
304	            $query = $query->getQuery();
305	        }
306	
307	        // Staff endpoints need to bind trashed customers/services for restore/hard-delete
308	        if (in_array($childType, [Customer::class, Service::class], true)) {
309	            $query->withTrashed();
310	        }
311	
312	        return $query;
313	    }
314	}
