106	                        'last_name' => $data['last_name'] ?? $professional->last_name,
107	                        'country_code' => $data['country_code'] ?? $professional->country_code,
108	                        'timezone' => $data['timezone'] ?? $professional->timezone,
109	                        'professional_type' => $resolveProfessionalType($data['professional_type'] ?? $professional->professional_type),
110	                        'handle_lc' => $data['handle_lc'],
111	                    ];
