12	use Illuminate\Support\Facades\Cache;
13	use Illuminate\Support\Facades\Log;
14	use Illuminate\Support\Facades\Storage;
15	
16	// V2: Public site payload caching with single-flight locking (prevents thundering herd). Handles 95% of traffic. Simplified in V2 — no more product payload caching.
17	class SiteCacheService
18	{
19	    private const MISS_SENTINEL = '__MISS__';
20	
21	    /** @var array<string, array<string, string|null>|null> */
22	    private array $brandPartnerEnrichmentCache = [];
23	
24	    public function __construct() {}
25	
26	    /**
27	     * Get public site payload (MOST CRITICAL - 95% of traffic)
28	     *
29	     * IMPORTANT: This must match the PublicSiteController response shape exactly.
30	     */
31	    public function getPublicSitePayload(string $subdomain): ?array
32	    {
33	        $subdomain = strtolower($subdomain);
34	
35	        $key = CacheKeyGenerator::publicSitePayload($subdomain);
36	        $cached = Cache::get($key);
37	
38	        if ($cached === self::MISS_SENTINEL) {
39	            return null;
40	        }
41	        if (is_array($cached)) {
42	            // Backward-compatible cache healing for payload shape changes.
43	            // Older cache entries may not include `services`.
44	            if (array_key_exists('services', $cached)) {
45	                $cached = $this->ensureBlockCollections($cached);
46	                $cached = $this->ensureProfessionalType(
47	                    $cached,
48	                    (string) data_get($cached, 'professional.id', '')
49	                );
50	                $cached = $this->safeWithStorePayload(
51	                    $cached,
52	                    (string) data_get($cached, 'professional.id', ''),
53	                    $subdomain
54	                );
55	
56	                if (! array_key_exists('legal', $cached)) {
57	                    $cached['legal'] = null;
58	                }
59	
60	                // Always resolve image variant paths to URLs (handles pre-URL-resolution cache entries)
61	                $site = $cached['site'] ?? null;
62	                if (is_array($site)) {
63	                    $professionalId = (string) data_get($cached, 'professional.id', '');
64	                    $cached['site'] = $this->safeHydrateSitePayload(
65	                        $site,
66	                        $professionalId,
67	                        '',
68	                        $subdomain
69	                    );
70	                }
71	
72	                Cache::put($key, $cached, now()->addMinutes(15));
73	
74	                return $cached;
75	            }
76	            Cache::forget($key);
77	        }
78	
79	        // Cache miss — acquire a per-subdomain fill lock so only one process rebuilds
80	        // the payload from the DB view while concurrent requests wait (single-flight).
81	        $fillLock = Cache::lock('site:fill:'.$subdomain, 10);
82	
83	        try {
84	            // Block up to 5 s for the lock; raises LockTimeoutException if it can't.
85	            $fillLock->block(5);
86	        } catch (\Illuminate\Contracts\Cache\LockTimeoutException) {
87	            // Another process is (or was) filling the cache.
88	            // Return whatever is now in cache, or null if it's still a miss.
89	            $warm = Cache::get($key);
90	            if ($warm === self::MISS_SENTINEL) {
91	                return null;
92	            }
93	
94	            return is_array($warm) ? $warm : null;
95	        }
96	
97	        try {
98	            // Double-check: the lock winner may have filled the cache while we waited.
99	            $rechecked = Cache::get($key);
100	            if ($rechecked === self::MISS_SENTINEL) {

100	            if ($rechecked === self::MISS_SENTINEL) {
101	                return null;
102	            }
103	            if (is_array($rechecked) && array_key_exists('services', $rechecked)) {
104	                return $rechecked;
105	            }
106	
107	            $row = PublicSitePayload::query()
108	                ->whereRaw('lower(subdomain) = ?', [$subdomain])
109	                ->first();
110	
111	            // View only contains published sites; if not found, treat as 404.
112	            if (! $row) {
113	                // Negative-cache briefly to reduce DB load from bot scans.
114	                Cache::put($key, self::MISS_SENTINEL, now()->addSeconds(30));
115	
116	                return null;
117	            }
118	
119	            $payload = $row->payload ?? [];
120	
121	            // The view's COALESCE guarantees services is always a jsonb array,
122	            // so a missing key is the only thing we have to defend against.
123	            $services = $payload['services'] ?? [];
124	
125	            $site = $payload['site'] ?? null;
126	            if (is_array($site)) {
127	                $site = $this->safeHydrateSitePayload(
128	                    $site,
129	                    (string) ($row->professional_id ?? ''),
130	                    (string) ($row->site_id ?? ''),
131	                    $subdomain
132	                );
133	            }
134	
135	            // Must match the controller response shape exactly.
136	            $links = is_array($payload['links'] ?? null) ? array_values($payload['links']) : [];
137	            $sections = is_array($payload['sections'] ?? null) ? array_values($payload['sections']) : [];
138	            $existingBlocks = is_array($payload['blocks'] ?? null) ? array_values($payload['blocks']) : [];
139	
140	            $data = [
141	                'published' => true,
142	                'site' => $site,
143	                'professional' => $payload['professional'] ?? null,
144	                'theme' => $payload['theme'] ?? null,
145	                'services' => $services,
146	                'links' => $links,
147	                'sections' => $sections,
148	                'blocks' => $this->buildCombinedBlocksPayload($links, $sections, $existingBlocks),
149	                'legal' => $payload['legal'] ?? null,
150	                // Preserve the store sub-object from the source payload so that
151	                // withStorePayload() below can lift selected_products + commission
152	                // settings out of payload.store. Without this, the rebuilt $data
153	                // has no 'store' key and withStorePayload falls through to empty
154	                // defaults — the front-end would see no featured products even
155	                // though the view row contains them.
156	                'store' => $payload['store'] ?? null,
157	            ];
158	            $data = $this->ensureProfessionalType($data, (string) ($row->professional_id ?? ''));
159	            $data = $this->safeWithStorePayload($data, (string) ($row->professional_id ?? ''), $subdomain);
160	            $data = $this->safeApplyBrandImageFallbacks($data, $subdomain);
161	
162	            Cache::put($key, $data, now()->addMinutes(15));
163	
164	            return $data;
165	        } finally {
166	            $fillLock->release();
167	        }
168	    }
