170	    /**
171	     * @param  array<string, mixed>  $payload
172	     * @return array<string, mixed>
173	     */
174	    private function applyBrandImageFallbacks(array $payload): array
175	    {
176	        $professional = $payload['professional'] ?? null;
177	        if (! is_array($professional) || ($professional['professional_type'] ?? null) === 'brand') {
178	            return $payload;
179	        }
180	
181	        $affiliateId = (string) ($professional['id'] ?? '');
182	        if (empty($affiliateId)) {
183	            return $payload;
184	        }
185	
186	        // JSON column is affiliate-controlled; use it only as a hint for which brand is configured.
187	        $brandPartner = $payload['site']['settings']['brand_partner'] ?? null;
188	        if (! is_array($brandPartner) || empty($brandPartner['professional_id'])) {
189	            return $payload;
190	        }
191	
192	        $claimedBrandId = (string) $brandPartner['professional_id'];
193	
194	        // BrandPartnerLink is the consent record — verify before using any brand data.
195	        $link = BrandPartnerLink::where('affiliate_professional_id', $affiliateId)
196	            ->where('brand_professional_id', $claimedBrandId)
197	            ->first();
198	
199	        if (! $link) {
200	            Log::warning('Brand-partner enrichment skipped: no verified link in consent table.', [
201	                'affiliate_id' => $affiliateId,
202	                'brand_id' => $claimedBrandId,
203	            ]);
204	
205	            return $payload;
206	        }
207	
208	        // Resolve brand_id from the verified link record, never from the mutable JSON.
209	        $brandId = (string) $link->brand_professional_id;
210	        $brandSite = Site::query()
211	            ->where('professional_id', $brandId)
212	            ->first();
213	
214	        if (! $brandSite) {
215	            return $payload;
216	        }
217	
218	        // Brand placeholders now live in site_media (pool=design, purpose=placeholder).
219	        // The service resolves variant URLs; we project them to { url, alt_text }
220	        // to match the new Hydrogen brand-design response shape.
221	        $designMedia = app(\App\Services\Media\BrandDesignMediaService::class)
222	            ->listDesignMedia((string) $brandSite->id);
223	
224	        if (empty($designMedia['placeholders'])) {
225	            return $payload;
226	        }
227	
228	        $placeholderImages = array_map(
229	            fn (array $p) => [
230	                'url' => $p['url'],
231	                'alt_text' => $p['alt_text'],
232	            ],
233	            $designMedia['placeholders']
234	        );
235	
236	        $imageKeys = ['gallery', 'content_images'];
237	
238	        foreach ($imageKeys as $key) {
239	            if (! isset($payload['site'][$key]) || ! is_array($payload['site'][$key])) {
240	                continue;
241	            }
242	
243	            if (empty($payload['site'][$key])) {
244	                $payload['site'][$key] = $placeholderImages;
245	            }
246	        }
247	
248	        return $payload;
249	    }

