333	
334	        $brandPartner = is_array($settings['brand_partner'] ?? null)
335	            ? $settings['brand_partner']
336	            : [];
337	
338	        $primaryLink = $links->firstWhere('slot', BrandPartnerLinkService::PRIMARY_SLOT);
339	        if ($primaryLink) {
