347	            ->filter(static fn ($link): bool => (int) $link->slot > BrandPartnerLinkService::PRIMARY_SLOT)
348	            ->sortBy('slot')
349	            ->map(static fn ($link): array => [
350	                'professional_id' => (string) $link->brand_professional_id,
